import 'dart:io';

void main(List<String> args) {
  final index = File(args[0]).readAsStringSync();
  final requiredFile = File(args[1]);

  final deepLinkPattern = RegExp(
    "https?://[^\"' <>()+,\t]*/releases/latest/download/[^\"' <>()+,\t]+",
  );

  Set<String> extractDeepLinks(String page) =>
      deepLinkPattern.allMatches(page).map((m) => m.group(0)!).toSet();

  final deepLinks = extractDeepLinks(index);

  final guaranteed = requiredFile
      .readAsLinesSync()
      .map((line) {
        final hash = line.indexOf('#');
        return (hash == -1 ? line : line.substring(0, hash)).trim();
      })
      .where((line) => line.isNotEmpty)
      .toSet();

  final offenders = <String>[];
  for (final url in deepLinks) {
    final asset = url.split('/download/').last;
    if (!guaranteed.contains(asset)) {
      offenders.add('$url (not in release_required_assets.txt)');
    }
  }
  print('extracted deep links:');
  for (final l in deepLinks) {
    print('  $l');
  }
  print('offenders: ${offenders.length}');
  for (final o in offenders) {
    print('  $o');
  }
  exit(offenders.isEmpty ? 0 : 1);
}
